(x, y, t) => {
  const wx1 = Math.sin(x * 0.015 + t * 0.2) * 20 + Math.cos(y * 0.012 - t * 0.15) * 15;
  const wy1 = Math.cos(y * 0.018 - t * 0.18) * 20 + Math.sin(x * 0.013 + t * 0.22) * 15;
  const mx = x + wx1, my = y + wy1;
  const wx2 = Math.sin(mx * 0.025 + my * 0.02 + t * 0.4) * 8 + Math.cos(mx * 0.02 - my * 0.03 + t * 0.3) * 6;
  const wy2 = Math.cos(my * 0.022 - mx * 0.018 + t * 0.35) * 8 + Math.sin(mx * 0.028 + my * 0.015 + t * 0.45) * 6;
  const sx = mx + wx2, sy = my + wy2;
  const src = [
    [160+Math.sin(t*0.5)*100, 80+Math.cos(t*0.35)*50, 0.07, 2.0, 1.0],
    [320+Math.cos(t*0.45)*100, 160+Math.sin(t*0.6)*50, 0.09, 1.7, 0.9],
    [240+Math.sin(t*0.25+2)*140, 120+Math.cos(t*0.4+1)*90, 0.055, 2.3, 1.1],
    [120+Math.cos(t*0.7+1)*80, 180+Math.sin(t*0.55+3)*60, 0.11, 1.5, 0.85],
    [360+Math.sin(t*0.35+4)*90, 60+Math.cos(t*0.8+2)*70, 0.065, 2.6, 1.05],
    [240+Math.cos(t*0.3+5)*120, 200+Math.sin(t*0.5)*80, 0.08, 1.9, 0.95],
    [80+Math.sin(t*0.6+3)*70, 40+Math.cos(t*0.45+2)*40, 0.13, 1.3, 0.8],
    [400+Math.cos(t*0.4+1)*60, 220+Math.sin(t*0.65+4)*50, 0.1, 2.1, 1.15],
    [200+Math.sin(t*0.55+6)*110, 140+Math.cos(t*0.38+3)*70, 0.075, 1.8, 1.0],
    [300+Math.cos(t*0.48+2)*90, 100+Math.sin(t*0.58+5)*60, 0.085, 2.4, 0.9]
  ];
  let aS = 0, iS = 0, harm = 0;
  for (const [sX, sY, f, sp, w] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    aS += Math.sin(d*f - t*sp) * w;
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5) * w;
    harm += Math.sin(d*f*0.5 - t*sp*0.3 + Math.sin(t*0.2)*2) * w * 0.5;
  }
  const n = src.length, act = aS/n, inh = iS/n, harmV = harm/n;
  const bg1 = (Math.sin(sx*0.035+sy*0.022+t*0.7) + Math.sin(sx*0.028-sy*0.035+t*0.9))/2;
  const bg2 = (Math.sin(sx*0.06+sy*0.045+t*1.3) + Math.cos(sx*0.05-sy*0.055+t*1.5))/2;
  const bg3 = Math.sin((sx+sy)*0.11+t*2.2)*0.3 + Math.sin((sx-sy)*0.09-t*1.8)*0.3;
