  const cx = 240, cy = 120;
  const dist = Math.sqrt((sx-cx)**2 + (sy-cy)**2);
  const ang = Math.atan2(sy-cy, sx-cx);
  const spiral = (Math.sin(dist*0.045-ang*4-t*1.3) + Math.sin(dist*0.035+ang*5-t*1.0) + Math.sin(dist*0.06-ang*2+t*0.8))*0.28;
  const radial = Math.sin(dist*0.08 - t*0.5) * Math.cos(ang*2 + t*0.3) * 0.3;
  const reaction = Math.tanh((act - inh*0.65 + bg*0.25 + spiral + radial + harmV*0.2)*2.0);
  const cell = Math.tanh((Math.sin(sx*0.13)*Math.sin(sy*0.13) + Math.sin((sx+sy)*0.09+t*0.8)*0.4 + Math.sin(sx*0.07-sy*0.11+t*0.6)*0.3)*1.4)*0.25;
  const micro = Math.sin(sx*0.3+sy*0.25+t*3)*Math.sin(sx*0.2-sy*0.35+t*2.5)*0.1;
  const blend = reaction*0.65 + cell*0.2 + micro*0.15;
  const v = blend*0.5+0.5;
  const pal = [
    [6,12,52],[12,48,85],[18,105,120],[45,155,130],[140,190,100],
    [220,195,70],[235,150,60],[210,95,55],[165,50,65],[90,25,55],[35,15,50],[6,12,52]
  ];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const lum = 0.85 + Math.sin(reaction*Math.PI)*0.15 + Math.abs(harmV)*0.05;
  const edge = Math.abs(reaction) > 0.65 ? 1.0 + (Math.abs(reaction)-0.65)*0.6 : 1.0;
  const chroma = 1.0 + Math.sin(ang*2 + t*0.5)*0.03;
  return [
    Math.min(255, (pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge*chroma)|0,
    Math.min(255, (pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge)|0,
    Math.min(255, (pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge*(2.0-chroma))|0
  ];
}
